/* Discord sources */
const IA_NOTES={server:'IA',channel:'seerahpro-bible-notes',id:'1514369926444617758'};
const IA_TRIN={server:'IA',channel:'trinity-refutation',id:'1514394727565230170'};
const IA_FATHER={server:'IA',channel:'is-allah-the-father',id:'1514756651360719051'};
const IA_CF={server:'IA',channel:'church-fathers',id:'1514489843357454447'};
const DR_MARK={server:'DR',channel:'mark',id:'1396880233910632508'};
const DR_M113={server:'DR',channel:'mark-1-1-3-debunked',id:'1368590776958980096'};
const DR_M13={server:'DR',channel:'mark-1-3',id:'1398950954815983696'};
const DR_I40={server:'DR',channel:'isaiah-40',id:'1368285215528714324'};
const DR_LORD={server:'DR',channel:'jesus-is-called-lord-debunked',id:'1368590745375608922'};
const DR_M2={server:'DR',channel:'mark-2-only-god-searches-hearts',id:'1399052391525126245'};
